function vacancyResponses(v){const allowed=Array.isArray(v.platforms)?v.platforms:[];return (data.responses||[]).filter(r=>r.vacancy===v.title&&allowed.includes(r.source))}function responseSourceLogo(source){return source==='HeadHunter'?'assets/integrations/headhunter.svg':source==='Работа.ру'?'assets/integrations/rabota.svg':source==='SuperJob'?'assets/integrations/superjob.svg':''}function responseDateLabel(r){const d=r.responseDate?new Date(r.responseDate):new Date();return d.toLocaleDateString('ru-RU',{day:'2-digit',month:'short',year:'numeric'}).replace(' г.','')}function responseCountLabel(n){const m=n%10, h=n%100;return n+' '+(m===1&&h!==11?'отклик':m>=2&&m<=4&&(h<12||h>14)?'отклика':'откликов')}function ensureResponseDates(){const now=new Date();(data.responses||[]).forEach((r,i)=>{if(!r.responseDate){if(Number(r.id)<20000){const d=new Date('2026-08-01T12:00:00');d.setDate(d.getDate()+(i*3)%48);r.responseDate=d.toISOString()}else r.responseDate=now.toISOString()}});saveResponses()}ensureResponseDates();
function saveResponses(){localStorage.setItem('teamdeck-vacancy-responses',JSON.stringify(data.responses||[]))}
