function initials(n){return n.split(' ').map(x=>x[0]).join('').slice(0,2)}function toast(t){const x=document.getElementById('toast');x.textContent=t;x.classList.add('show');setTimeout(()=>x.classList.remove('show'),2200)}
function animateMetricNumbers(root){(root||document).querySelectorAll('.kpi .num,.quality-num').forEach(el=>{const text=el.textContent.trim(),match=text.match(/([0-9]+(?:[,.][0-9]+)?)/);if(!match)return;const raw=match[1],value=Number(raw.replace(',','.')),prefix=text.slice(0,match.index),suffix=text.slice(match.index+raw.length);let started=performance.now();const duration=850;function tick(now){const progress=Math.min((now-started)/duration,1),ease=1-Math.pow(1-progress,3),current=value*ease;let formatted=value%1?current.toFixed(1).replace('.',','):Math.round(current).toString();el.textContent=prefix+formatted+suffix;if(progress<1)requestAnimationFrame(tick)}requestAnimationFrame(tick)})}
