function effectiveEmployeeStatusClass(person){return offboardingStatusFor(person)?'offboarding-status':employeeStatusClass(person.status)}
function offboardingDaysLeft(p){return Math.ceil((new Date(`${p.lastDay}T23:59:59`)-new Date())/86400000)}
function employeeCountLabel(n){const mod10=n%10,mod100=n%100;return `${n} ${mod10===1&&mod100!==11?'сотрудник':mod10>=2&&mod10<=4&&(mod100<10||mod100>=20)?'сотрудника':'сотрудников'}`}function renderOffboarding(){const funnel=document.getElementById('offboardingFunnel');if(!funnel)return;const taskTotal=offboardingPeople.reduce((sum,p)=>sum+(offboardingChecks[p.stage]?.length||0)-offboardingChecksFor(p).length,0),soon=offboardingPeople.filter(p=>offboardingDaysLeft(p)>=0&&offboardingDaysLeft(p)<=7).length,risks=offboardingPeople.filter(p=>offboardingDaysLeft(p)<0).length;document.getElementById('offboardingTotal').textContent=offboardingPeople.length;document.getElementById('offboardingSoon').textContent=soon;document.getElementById('offboardingTasks').textContent=Math.max(0,taskTotal);document.getElementById('offboardingRisks').textContent=risks;funnel.innerHTML=offboardingStages.map((stage,index)=>{const people=offboardingPeople.filter(p=>offboardingStageFor(p)===index);return `<div class="offboarding-stage" data-stage="${index}" ondragover="event.preventDefault();this.classList.add('drag-over')" ondragleave="this.classList.remove('drag-over')" ondrop="dropOffboarding(event,${index})"><div class="offboarding-stage-head"><b>${stage}</b><span class="stage-count">${employeeCountLabel(people.length)}</span></div><div class="offboarding-stage-people">${people.map(p=>{const left=offboardingDaysLeft(p),status=left<0?'Просрочено':left<=7?'Скоро':'По плану';return `<div class="offboarding-person" draggable="true" ondragstart="event.dataTransfer.setData('offboarding-id',${p.id})" onclick="openOffboardingPerson(${p.id})">${p.photo?`<img class="offboarding-person-avatar photo" src="${p.photo}" alt="${p.name}">`:`<span class="offboarding-person-avatar">${initials(p.name)}</span>`}<span><b>${p.name}</b><small>${p.role}</small><em class="offboarding-card-status ${left<0?'risk':left<=7?'soon':''}">${status} · ${p.lastDay}</em></span></div>`}).join('')||'<span class="mini">Перетащите сотрудника сюда</span>'}</div></div>`}).join('');renderOffboardingCalendar();renderOffboardingSecurity()}
function dropOffboarding(e,stage){e.preventDefault();e.currentTarget.classList.remove('drag-over');const id=+e.dataTransfer.getData('offboarding-id'),person=offboardingPeople.find(x=>x.id===id);if(!person)return;person.stage=stage;const checks=JSON.parse(localStorage.getItem('teamdeck-offboarding-checks')||'{}');checks[id]=[];localStorage.setItem('teamdeck-offboarding-checks',JSON.stringify(checks));saveOffboarding();renderOffboarding();renderCompanyTeam();toast(`${person.name}: этап изменён на «${offboardingStages[stage]}»`)}
let offboardingCalendarMonth=new Date(2026,8,1);function renderOffboardingCalendar(){const box=document.getElementById('offboardingCalendar');if(!box)return;const names=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],year=offboardingCalendarMonth.getFullYear(),month=offboardingCalendarMonth.getMonth(),title=new Intl.DateTimeFormat('ru-RU',{month:'long',year:'numeric'}).format(offboardingCalendarMonth),first=(new Date(year,month,1).getDay()+6)%7,days=new Date(year,month+1,0).getDate(),prevDays=new Date(year,month,0).getDate(),eventsByDate={};offboardingPeople.forEach(p=>{if(p.lastDay){(eventsByDate[p.lastDay]||(eventsByDate[p.lastDay]=[])).push(p)}});let html=`<div class="calendar-head"><span class="mini">Нажмите на событие, чтобы открыть чек-лист</span><div class="calendar-nav"><button class="btn" type="button" onclick="changeOffboardingMonth(-1)" aria-label="Предыдущий месяц">‹</button><div class="calendar-title">${title}</div><button class="btn" type="button" onclick="changeOffboardingMonth(1)" aria-label="Следующий месяц">›</button></div></div><div class="calendar-grid offboarding-month-grid">${names.map(n=>`<div class="calendar-weekday">${n}</div>`).join('')}`;for(let i=0;i<first;i++)html+=`<div class="calendar-day muted"><div class="day-number">${prevDays-first+i+1}</div></div>`;for(let d=1;d<=days;d++){const iso=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,people=eventsByDate[iso]||[],today=iso===new Date().toISOString().slice(0,10);html+=`<div class="calendar-day ${today?'today':''}"><div class="day-number">${d}</div>${people.map(p=>`<button type="button" class="calendar-event offboarding-calendar-event offboarding-stage-${offboardingStageFor(p)}" onclick="openOffboardingPerson(${p.id})"><span>${p.name}</span><small>${offboardingStages[offboardingStageFor(p)]}</small></button>`).join('')}</div>`}const total=first+days;for(let i=1;i<=42-total;i++)html+=`<div class="calendar-day muted"><div class="day-number">${i}</div></div>`;box.innerHTML=html+'</div>'}function changeOffboardingMonth(offset){offboardingCalendarMonth=new Date(offboardingCalendarMonth.getFullYear(),offboardingCalendarMonth.getMonth()+offset,1);renderOffboardingCalendar()}

function renderOffboardingSecurity(){const box=document.getElementById('offboardingSecurity');if(!box)return;const pending=offboardingPeople.filter(p=>offboardingStageFor(p)<4).length,critical=offboardingPeople.filter(p=>offboardingStageFor(p)===4).length;box.innerHTML=`<div class="security-summary"><span class="security-icon">!</span><div><b>${critical} сотрудника на этапе закрытия доступов</b><small>${pending} процесса ещё требуют подготовки доступов и оборудования</small></div></div><div class="security-line"><span>Доступы к системам</span><b>${critical?'Требуют проверки':'В графике'}</b></div><div class="security-line"><span>Ответственный</span><b>IT-безопасность</b></div><div class="security-line"><span>Последняя проверка</span><b>Сегодня, 09:30</b></div>`}
let selectedOffboardingEmployeeId=null;
function openOffboardingStart(){selectedOffboardingEmployeeId=null;document.getElementById('modalContent').innerHTML=`<div class="modalhead"><h2>Начать оффбординг</h2><button class="close" onclick="closeModal()">×</button></div><p class="mini">Выберите сотрудника из структуры компании. Можно открыть департамент или воспользоваться поиском.</p><div class="offboarding-picker-toolbar"><input class="input" id="offboardingEmployeeSearch" placeholder="Поиск по имени, должности или департаменту…" oninput="renderOffboardingEmployeePicker()"></div><div class="offboarding-departments" id="offboardingDepartments"></div><div class="offboarding-picker-list" id="offboardingPickerList"></div><div class="formgrid offboarding-date-fields"><div class="field"><label>Последний рабочий день</label><input class="input" id="offboardingLastDay" type="date" value="${new Date(Date.now()+86400000*14).toISOString().slice(0,10)}"></div><div class="field"><label>Причина ухода</label><select class="input" id="offboardingReason"><option>По собственному желанию</option><option>Сокращение</option><option>Окончание контракта</option><option>Переход в другую компанию</option><option>Другое</option></select></div><div class="field full"><label>Комментарий</label><textarea class="input" id="offboardingComment" rows="3" placeholder="Дополнительная информация…"></textarea></div></div><div class="modalfoot"><button class="btn cancel-button" onclick="closeModal()">Отмена</button><button class="btn primary" id="offboardingAddButton" disabled onclick="createOffboarding()">Добавить в воронку</button></div>`;renderOffboardingEmployeePicker();openModal()}
function renderOffboardingEmployeePicker(){const search=(document.getElementById('offboardingEmployeeSearch')?.value||'').trim().toLowerCase(),departments=[...new Set(companyPeople.map(p=>p.department))].sort((a,b)=>a.localeCompare(b,'ru'));const active=document.getElementById('offboardingActiveDepartment')?.value||'';const available=companyPeople.filter(p=>!offboardingPeople.some(x=>Number(x.sourceCompanyId)===Number(p.id)));const filtered=available.filter(p=>(!search||`${p.name} ${p.role} ${p.department}`.toLowerCase().includes(search))&&(!active||p.department===active));const departmentsBox=document.getElementById('offboardingDepartments');if(departmentsBox)departmentsBox.innerHTML=`<button class="offboarding-department-chip ${!active?'active':''}" onclick="setOffboardingDepartment('')">Все департаменты</button>${departments.map(d=>`<button class="offboarding-department-chip ${active===d?'active':''}" onclick="setOffboardingDepartment('${d.replace(/'/g,"\\'")}')">${d}<span>${available.filter(p=>p.department===d).length}</span></button>`).join('')}`;const list=document.getElementById('offboardingPickerList');if(list)list.innerHTML=filtered.map(p=>`<button type="button" class="offboarding-picker-card ${selectedOffboardingEmployeeId===p.id?'selected':''}" onclick="selectOffboardingEmployee(${p.id})"><span class="offboarding-picker-avatar">${p.photo?`<img src="${p.photo}" alt="${p.name}">`:initials(p.name)}</span><span><b>${p.name}</b><small>${p.role} · ${p.department}</small></span><span class="offboarding-picker-check">${selectedOffboardingEmployeeId===p.id?'✓':''}</span></button>`).join('')||'<div class="empty">Сотрудники не найдены или уже добавлены в оффбординг</div>'}
function setOffboardingDepartment(department){let hidden=document.getElementById('offboardingActiveDepartment');if(!hidden){hidden=document.createElement('input');hidden.type='hidden';hidden.id='offboardingActiveDepartment';document.getElementById('modalContent').appendChild(hidden)}hidden.value=department;renderOffboardingEmployeePicker()}
function selectOffboardingEmployee(id){selectedOffboardingEmployeeId=id;const button=document.getElementById('offboardingAddButton');if(button)button.disabled=false;renderOffboardingEmployeePicker()}
function createOffboarding(){const id=Number(selectedOffboardingEmployeeId),employee=companyPeople.find(p=>p.id===id);if(!employee){toast('Выберите сотрудника');return}if(offboardingPeople.some(p=>Number(p.sourceCompanyId)===id)){toast('Сотрудник уже на оффбординге');return}offboardingPeople.push({id:Date.now(),name:employee.name,role:employee.role,department:employee.department,manager:employee.manager,email:employee.email,phone:employee.phone,photo:employee.photo||'',stage:0,lastDay:document.getElementById('offboardingLastDay').value,reason:document.getElementById('offboardingReason').value,comment:document.getElementById('offboardingComment').value,sourceCompanyId:id,addedAt:Date.now()});saveOffboarding();renderOffboarding();renderCompanyTeam();closeModal();toast(`${employee.name} добавлен в оффбординг`)}
function openOffboardingPerson(id){const person=offboardingPeople.find(p=>p.id===id);if(!person)return;const stage=offboardingStageFor(person),done=offboardingChecksFor(person),tasks=offboardingChecks[stage]||[],complete=tasks.length>0&&tasks.every((_,i)=>done.includes(i)),left=offboardingDaysLeft(person),isLast=stage===offboardingStages.length-1;document.getElementById('modalContent').innerHTML=`<div class="modalhead"><div><h2>${person.name}</h2><div class="mini" style="margin-top:4px">${person.role} · ${person.department}</div></div><button class="close" onclick="closeModal()">×</button></div><div class="offboarding-profile-meta"><span class="badge blue">${offboardingStages[stage]}</span><span class="mini">Последний рабочий день: ${person.lastDay}</span><span class="mini">${person.reason}</span></div><h3>Чек-лист этапа</h3><div class="onboarding-modal-checklist">${tasks.map((task,i)=>`<label class="onboarding-check ${done.includes(i)?'checked':''}"><input type="checkbox" ${done.includes(i)?'checked':''} onchange="toggleOffboardingCheck(${id},${i},this.checked)"><span class="checkmark"></span><span>${task}</span></label>`).join('')}</div>${left<0?'<p class="offboarding-warning">Срок ухода прошёл — проверьте незакрытые задачи.</p>':''}<div class="modalfoot"><button class="btn" onclick="closeModal()">Закрыть</button><button class="btn primary onboarding-next" ${complete?'':'disabled'} onclick="${isLast?`completeOffboarding(${id})`:`moveToNextOffboarding(${id})`}">${isLast?'Завершить оффбординг':'Следующий этап'}</button></div>`;openModal()}
function toggleOffboardingCheck(id,index,checked){const saved=JSON.parse(localStorage.getItem('teamdeck-offboarding-checks')||'{}');saved[id]=saved[id]||[];if(checked&&!saved[id].includes(index))saved[id].push(index);if(!checked)saved[id]=saved[id].filter(x=>x!==index);localStorage.setItem('teamdeck-offboarding-checks',JSON.stringify(saved));renderOffboarding();openOffboardingPerson(id)}
function moveToNextOffboarding(id){const person=offboardingPeople.find(x=>x.id===id);if(!person)return;const tasks=offboardingChecks[offboardingStageFor(person)]||[],done=offboardingChecksFor(person);if(done.length!==tasks.length||offboardingStageFor(person)>=offboardingStages.length-1)return;person.stage=offboardingStageFor(person)+1;const checks=JSON.parse(localStorage.getItem('teamdeck-offboarding-checks')||'{}');checks[id]=[];localStorage.setItem('teamdeck-offboarding-checks',JSON.stringify(checks));saveOffboarding();renderOffboarding();renderCompanyTeam();closeModal();toast(`${person.name}: переведён на этап «${offboardingStages[person.stage]}»`)}
function completeOffboarding(id){const person=offboardingPeople.find(x=>x.id===id);if(!person||offboardingStageFor(person)!==offboardingStages.length-1)return;const done=offboardingChecksFor(person),tasks=offboardingChecks[offboardingStages.length-1]||[];if(done.length!==tasks.length){toast('Сначала выполните все пункты чек-листа');return}offboardingPeople=offboardingPeople.filter(x=>x.id!==id);const completedDemoOffboarding=JSON.parse(localStorage.getItem('teamdeck-offboarding-demo-completed')||'[]');if(!completedDemoOffboarding.includes(person.id))completedDemoOffboarding.push(person.id);localStorage.setItem('teamdeck-offboarding-demo-completed',JSON.stringify(completedDemoOffboarding));if(person.sourceCompanyId){companyPeople=companyPeople.filter(x=>Number(x.id)!==Number(person.sourceCompanyId));saveCompanyPeople()}saveOffboarding();const checks=JSON.parse(localStorage.getItem('teamdeck-offboarding-checks')||'{}');delete checks[id];localStorage.setItem('teamdeck-offboarding-checks',JSON.stringify(checks));renderOffboarding();renderCompanyTeam();closeModal();toast(`${person.name}: оффбординг завершён`)}
function restoreActiveView(){let saved=localStorage.getItem('teamdeck-active-view');if(localStorage.getItem('teamdeck-team-nav-migrated')!=='1'){if(saved==='team')saved='recruitment';localStorage.setItem('teamdeck-team-nav-migrated','1')}const target=saved&&document.getElementById(saved)?saved:'dashboard';localStorage.setItem('teamdeck-active-view',target);document.querySelectorAll('#nav button').forEach(x=>x.classList.toggle('active',x.dataset.view===target));document.querySelectorAll('.views').forEach(v=>v.classList.toggle('active',v.id===target));document.body.classList.add('app-ready')}function nav(){document.querySelectorAll('#nav button').forEach(b=>b.onclick=()=>{const current=document.querySelector('.views.active')?.id;if(current===b.dataset.view)return;localStorage.setItem('teamdeck-active-view',b.dataset.view);document.querySelectorAll('#nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.views').forEach(v=>v.classList.remove('active'));document.getElementById(b.dataset.view).classList.add('active');replayPageAnimation(b.dataset.view);if(b.dataset.view==='vacancies')renderVacancies();if(b.dataset.view==='candidates')renderCandidates();if(b.dataset.view==='pipeline')renderPipeline();if(b.dataset.view==='integrations')renderIntegrations();if(b.dataset.view==='team')renderCompanyTeam()})}initTheme();initSecurity();initTemplates();restoreActiveView();nav();initAuth();renderOnboarding();document.getElementById('profileTrigger').onclick=toggleProfileMenu;document.addEventListener('click',e=>{const launcher=document.querySelector('.profile-launcher');if(launcher&&!launcher.contains(e.target)){document.getElementById('profileMenu').classList.remove('open')}});
let pendingDelete=null;function openDeleteConfirm(type,id){const item=type==='vacancy'?data.vacancies.find(x=>x.id===id):data.candidates.find(x=>x.id===id);if(!item)return;pendingDelete={type,id};const label=type==='vacancy'?'вакансию':'кандидата',name=type==='vacancy'?item.title:item.name;document.getElementById('modalContent').innerHTML=`<div class="modalhead"><h2>Удалить ${label}?</h2><button class="close" onclick="closeModal()">×</button></div><div class="delete-confirm"><div class="delete-confirm-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 7h16M10 11v6M14 11v6M6 7l1 13h10l1-13M9 7V4h6v3"/></svg></div><div><p class="delete-confirm-title">${name}</p><p class="mini">Это действие нельзя отменить. Запись будет удалена из списка.</p></div></div><div class="modalfoot"><button class="btn cancel-button" type="button" onclick="closeModal()">Отмена</button><button class="btn delete-confirm-action" type="button" onclick="confirmDelete()">Удалить</button></div>`;openModal()}function confirmDelete(){if(!pendingDelete)return;const {type,id}=pendingDelete;if(type==='vacancy'){data.vacancies=data.vacancies.filter(x=>x.id!==id);save();renderVacancies();toast('Вакансия удалена')}else{data.candidates=data.candidates.filter(x=>x.id!==id);save();renderCandidates();renderVacancies();toast('Кандидат удалён')}pendingDelete=null;closeModal()}function deleteVacancy(id){openDeleteConfirm('vacancy',id)}function sendCandidateDeleteApproval(id){const c=data.candidates.find(x=>x.id===id),comment=document.getElementById('candidateApprovalComment')?.value.trim();if(!comment){toast('Добавьте комментарий для согласования');return}c.deleteApprovalRequested=true;c.deleteApprovalArchived=false;c.deleteApprovalStatus='Новое';c.deleteApprovalComment=comment;c.deleteApprovalResponse='';c.deleteApprovalViewed=false;c.deleteApprovalRequestedAt=new Date().toISOString();save();updateApprovalBadge();closeModal();toast('Запрос на удаление отправлен руководителю департамента')}
function approvalNowLabel(){return new Date().toLocaleDateString('ru-RU',{day:'2-digit',month:'long',year:'numeric'})}
function archiveApprovalForCandidate(c,resolution,response){if(!Array.isArray(data.approvalArchive))data.approvalArchive=[];data.approvalArchive.unshift({id:'approval-'+c.id+'-'+Date.now(),candidateId:c.id,name:c.name,role:c.role,vac:c.vac,source:c.source,photo:c.photo||'',rating:c.resumeAnalysis?.score??c.rating??0,comment:c.deleteApprovalComment||'Комментарий не указан',response:response||c.deleteApprovalResponse||'',resolution,requestedAt:c.deleteApprovalRequestedAt||new Date().toISOString(),resolvedAt:new Date().toISOString(),resolvedBy:'CEO'});c.deleteApprovalArchived=true;c.deleteApprovalStatus=resolution}
function migrateCompletedApprovals(){if(!Array.isArray(data.approvalArchive))data.approvalArchive=[];let changed=false;data.candidates.forEach(c=>{if(c.deleteApprovalRequested&&c.deleteApprovalStatus==='Продолжить диалог'&&!c.deleteApprovalArchived&&!data.approvalArchive.some(a=>a.candidateId===c.id)){archiveApprovalForCandidate(c,'Продолжить диалог',c.deleteApprovalResponse);changed=true}});if(changed)save();return changed}
function approvalRequests(){migrateCompletedApprovals();return data.candidates.filter(c=>c.deleteApprovalRequested&&!c.deleteApprovalArchived)}
function approvalArchive(){migrateCompletedApprovals();return Array.isArray(data.approvalArchive)?data.approvalArchive:[]}
function updateApprovalBadge(){const el=document.getElementById('approvalCount');if(!el)return;const count=approvalRequests().filter(c=>!c.deleteApprovalViewed).length;el.textContent=count;el.classList.toggle('hidden',count===0)}
function approvalPersonMarkup(item){const rating=Number(item.rating||0);return `<div class="person"><span class="avatar ${item.photo?'photo':''}">${item.photo?`<img src="${item.photo}" alt="${item.name}">`:initials(item.name)}</span><div><b>${item.name}</b><div class="mini">${item.role} · ${item.vac}</div></div></div><div class="approval-request-meta"><span>AI-рейтинг <b>★ ${rating.toFixed(1)} / 5,0</b></span><span>Решение: ${item.resolution||'—'}</span><span>${item.resolvedAt?`Дата: ${new Date(item.resolvedAt).toLocaleDateString('ru-RU')}`:'Отправил: HR'}</span></div>`}
function openApprovals(view='active'){const active=approvalRequests();const archive=approvalArchive();active.forEach(c=>c.deleteApprovalViewed=true);save();updateApprovalBadge();const items=view==='archive'?archive:view==='all'?[...active,...archive]:active;const body=items.length?items.map(item=>{const isArchive=!!item.resolution;return `<article class="approval-request-card ${isArchive?'approval-archived-card':''}">${approvalPersonMarkup(isArchive?item:item)}${isArchive?`<div class="approval-request-message"><b>Сообщение HR</b><p>${item.comment||'Комментарий не указан'}</p></div>${item.response?`<div class="approval-response"><b>Ответ CEO</b><p>${item.response}</p></div>`:''}<div class="approval-archive-meta">Обращение завершено и сохранено в архиве</div>`:`<div class="approval-request-message"><b>Сообщение HR</b><p>${item.deleteApprovalComment||'Комментарий не указан'}</p></div>${item.deleteApprovalResponse?`<div class="approval-response"><b>Ответ CEO</b><p>${item.deleteApprovalResponse}</p></div>`:''}<div class="approval-request-actions"><button class="btn approval-approve" onclick="approveCandidateDeletion(${item.id})">Согласовать удаление</button><button class="btn" onclick="openApprovalReply(${item.id})">Ответить HR</button></div>`}</article>`}).join(''):`<div class="approval-empty"><div class="approval-empty-icon">✓</div><h3>${view==='archive'?'Архив пуст':'Нет активных запросов'}</h3><p>${view==='archive'?'Завершённые обращения появятся здесь.':'Новые запросы от HR появятся здесь.'}</p></div>`;document.getElementById('modalContent').innerHTML=`<div class="modalhead"><div><h2>Согласования</h2><span class="mini">Запросы на удаление кандидатов</span></div><button class="close" onclick="closeModal()">×</button></div><div class="approval-toolbar"><button class="approval-filter ${view==='active'?'active':''}" onclick="openApprovals('active')">Активные <b>${active.length}</b></button><button class="approval-filter ${view==='archive'?'active':''}" onclick="openApprovals('archive')">Архив <b>${archive.length}</b></button><button class="approval-filter ${view==='all'?'active':''}" onclick="openApprovals('all')">Все</button>${view==='archive'&&archive.length?`<button class="btn approval-clear-archive" onclick="clearApprovalArchive()">Очистить архив</button>`:''}</div><div class="approval-list">${body}</div>`;openModal()}
function clearApprovalArchive(){if(!approvalArchive().length)return;if(!window.confirm('Очистить архив завершённых обращений? История решений будет удалена.'))return;data.approvalArchive=[];save();openApprovals('archive');toast('Архив согласований очищен')}
function approveCandidateDeletion(id){const c=data.candidates.find(x=>x.id===id);if(!c)return;archiveApprovalForCandidate(c,'Удаление согласовано','Кандидат удалён после согласования CEO.');data.candidates=data.candidates.filter(x=>x.id!==id);save();renderCandidates();renderVacancies();updateApprovalBadge();openApprovals('active');toast('Удаление кандидата согласовано')}
function openApprovalReply(id){const c=data.candidates.find(x=>x.id===id);if(!c)return;document.getElementById('modalContent').innerHTML=`<div class="modalhead"><h2>Ответ HR</h2><button class="close" onclick="openApprovals()">×</button></div><p class="mini">Сообщение по кандидату: <b>${c.name}</b></p><div class="field"><label>Ваше решение</label><textarea class="input approval-reply-input" id="approvalReplyText" rows="5" placeholder="Например: продолжаем диалог с кандидатом…">${c.deleteApprovalResponse||'Предлагаю продолжить диалог с кандидатом.'}</textarea></div><div class="modalfoot"><button class="btn" onclick="openApprovals()">Назад</button><button class="btn primary" onclick="sendApprovalReply(${c.id})">Отправить HR</button></div>`;openModal()}function sendApprovalReply(id){const c=data.candidates.find(x=>x.id===id),reply=document.getElementById('approvalReplyText')?.value.trim();if(!reply){toast('Введите ответ для HR');return}archiveApprovalForCandidate(c,'Продолжить диалог',reply);c.deleteApprovalResponse=reply;c.deleteApprovalViewed=true;save();updateApprovalBadge();openApprovals('active');toast('Ответ отправлен HR и обращение перемещено в архив')}
function deleteCandidate(id){const c=data.candidates.find(x=>x.id===id);if(!c)return;const score=Number(candidateRating(c));if(score>=4.5){document.getElementById('modalContent').innerHTML=`<div class="modalhead"><h2>Нужно согласование</h2><button class="close" onclick="closeModal()">×</button></div><p>Кандидата с оценкой <b>${score.toFixed(1)} / 5,0</b> нельзя удалить без согласования с руководителем департамента.</p><div class="field"><label>Комментарий для руководителя</label><textarea class="input" id="candidateApprovalComment" rows="4" placeholder="Укажите причину запроса согласования…">${c.deleteApprovalComment||''}</textarea></div><div class="modalfoot"><button class="btn cancel-button" onclick="closeModal()">Отмена</button><button class="btn primary" onclick="sendCandidateDeleteApproval(${c.id})">Запросить согласование</button></div>`;openModal();return}openDeleteConfirm('candidate',id)}
